import{c as e,Q as i,j as o,m as a}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Claude Code 社群實踐深度研究報告","description":"","frontmatter":{"title":"Claude Code 社群實踐深度研究報告","date":"2026-06-07T00:00:00.000Z","research_period":"2025-10 ~ 2026-06","sources_count":32,"topics":["hooks","security","orchestration","memory","cost-optimization","enterprise","CI/CD","testing","skill-design"]},"headers":[],"relativePath":"research/reports/2026-06-07-claude-code-community-practices-report.md","filePath":"research/reports/2026-06-07-claude-code-community-practices-report.md","lastUpdated":1780842316000}'),l={name:"research/reports/2026-06-07-claude-code-community-practices-report.md"};function r(s,t,n,d,c,h){return i(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="claude-code-社群實踐深度研究報告-2026-06-07" tabindex="-1">Claude Code 社群實踐深度研究報告（2026-06-07） <a class="header-anchor" href="#claude-code-社群實踐深度研究報告-2026-06-07" aria-label="Permalink to &quot;Claude Code 社群實踐深度研究報告（2026-06-07）&quot;">​</a></h1><blockquote><p>涵蓋 32 篇 Twitter/GitHub/Blogs 社群實踐文章，研究期間 2025-10 ~ 2026-06。 <strong>數字標注</strong>：<code>[來源宣稱]</code> = 原作者自述，尚未獨立驗證；<code>[已驗證]</code> = 有可重現實驗或第三方交叉確認。</p></blockquote><hr><h2 id="tl-dr-—-五大核心-insights" tabindex="-1">TL;DR — 五大核心 Insights <a class="header-anchor" href="#tl-dr-—-五大核心-insights" aria-label="Permalink to &quot;TL;DR — 五大核心 Insights&quot;">​</a></h2><ol><li><p><strong>Hooks 是唯一可信任的確定性層</strong>：LLM 本身不可做決策（路由/阻斷），hooks 的 exit code 語義（exit 0=允許、exit 2=阻斷、exit 1=非阻斷）是安全策略的基石，混用導致策略全面失效。</p></li><li><p><strong>Context Drift 是最大生產力殺手</strong>：3+ 小時長 session 後每 5 任務出現 1 次 regression，「One task, one session」反直覺但 empirically 驗證有效（Jamie Cole 47 任務 retrospective）。</p></li><li><p><strong>並行不等於正確</strong>：5 模型 adversarial debate 的 bug detection 從 53%→80%，但成本不等比例增加；Claude+Gemini 雙模型達 5 模型天花板的 91%，是最優性價比點。</p></li><li><p><strong>Token 優化的最大槓桿在結構而非內容</strong>：AST graph 注入（71x token 削減）、RAG-over-codebase（70-85% 削減）、memory 分層（60-80% 節省）均來自架構改變，不是壓縮 prompt 文字。</p></li><li><p><strong>安全漏洞的根因是預設信任</strong>：GitHub Action Read tool 預設允許讀任意路徑（含 <code>/proc/self/environ</code>）暴露 API key，已在 v2.1.128 修補；prompt injection 四向量中「reputation framing」（自稱 compliance review）是最隱蔽的。</p></li></ol><hr><h2 id="一、研究方法與範疇" tabindex="-1">一、研究方法與範疇 <a class="header-anchor" href="#一、研究方法與範疇" aria-label="Permalink to &quot;一、研究方法與範疇&quot;">​</a></h2><h3 id="_1-1-來源分布" tabindex="-1">1.1 來源分布 <a class="header-anchor" href="#_1-1-來源分布" aria-label="Permalink to &quot;1.1 來源分布&quot;">​</a></h3><table tabindex="0"><thead><tr><th>來源類型</th><th>篇數</th><th>代表</th></tr></thead><tbody><tr><td>GitHub repos / README</td><td>8</td><td>claude-mem, Graphify, claudelab</td></tr><tr><td>個人 blog / Substack</td><td>12</td><td>Jamie Cole, Ian Paterson, Eva Khmelinskaya</td></tr><tr><td>企業技術博客</td><td>7</td><td>General Analysis, Boldare, Branch8, Dyad AI</td></tr><tr><td>arXiv 論文</td><td>2</td><td>VILA-Lab 2604.14228, Multi-model debate</td></tr><tr><td>安全研究報告</td><td>2</td><td>Microsoft Security Research, Hannecke</td></tr><tr><td>社群討論整理</td><td>1</td><td>Prompt Shelf hooks events</td></tr></tbody></table><h3 id="_1-2-主題覆蓋" tabindex="-1">1.2 主題覆蓋 <a class="header-anchor" href="#_1-2-主題覆蓋" aria-label="Permalink to &quot;1.2 主題覆蓋&quot;">​</a></h3><p>11 個主題群：A 權限 Hooks（3）、B 安全防禦（3）、C 並行 Orchestration（3）、D 成本優化（3）、E 記憶系統（3）、F 企業部署（2）、G Spec 工作流程（3）、H CI/CD Routines（3）、I Skill 設計（2）、J 大型專案（2）、K 測試自動化（2）。</p><h3 id="_1-3-誠實度聲明" tabindex="-1">1.3 誠實度聲明 <a class="header-anchor" href="#_1-3-誠實度聲明" aria-label="Permalink to &quot;1.3 誠實度聲明&quot;">​</a></h3><ul><li>大多數 ROI 數字（成本削減 72%、覆蓋率 +30%）為<strong>來源宣稱</strong>，缺乏獨立複現環境</li><li>學術論文（arXiv）數字相對可信但限定實驗設置</li><li>個人 retrospective（Jamie Cole、Ian Paterson）具體細節豐富但樣本單一</li></ul><hr><h2 id="二、主題深度分析-11-個主題群" tabindex="-1">二、主題深度分析（11 個主題群） <a class="header-anchor" href="#二、主題深度分析-11-個主題群" aria-label="Permalink to &quot;二、主題深度分析（11 個主題群）&quot;">​</a></h2><h3 id="主題-a-permission-hooks-架構" tabindex="-1">主題 A：Permission Hooks 架構 <a class="header-anchor" href="#主題-a-permission-hooks-架構" aria-label="Permalink to &quot;主題 A：Permission Hooks 架構&quot;">​</a></h3><h4 id="核心發現" tabindex="-1">核心發現 <a class="header-anchor" href="#核心發現" aria-label="Permalink to &quot;核心發現&quot;">​</a></h4><p><strong>A1 — 雙層架構（Dyad AI）</strong></p><ul><li>第一層：確定性 regex，延遲 &lt;1ms</li><li>第二層：Claude Sonnet LLM 分類器（GREEN/YELLOW/RED），25s timeout</li><li>環境變數 kill-switch：<code>DYAD_DISABLE_CLAUDE_CODE_HOOKS=true</code></li><li>關鍵設計：第一層 pass 才進第二層，不跑 LLM 在已知安全操作上</li></ul><p><strong>A2 — Narrowness Principle（Jangwook Kim）</strong></p><ul><li>每個 hook 只處理<strong>一條規則</strong>，不合併多邏輯</li><li>exit 0=允許，exit 2=阻斷（Unix 強制，非 convention）</li><li>fixture-driven 測試：每個 hook 必須有失敗 fixture，防止靜默通過</li></ul><p><strong>A3 — Hook Events 完整圖譜（Prompt Shelf）</strong></p><ul><li>27 distinct hook events，含 subtypes 共 32+</li><li><strong>關鍵陷阱</strong>：exit 1 非阻斷（Unix convention），exit 2 才阻斷——混淆導致安全策略無效</li><li>PostToolBatch 可做 TSV 格式 token/cost 記錄，用於 audit trail</li></ul><h4 id="最佳實踐建議" tabindex="-1">最佳實踐建議 <a class="header-anchor" href="#最佳實踐建議" aria-label="Permalink to &quot;最佳實踐建議&quot;">​</a></h4><ol><li>確定性邏輯（regex/字串匹配）一律在 hook 層；LLM 只做 classification label，不做 routing decision</li><li>Hook 按 Narrowness Principle 拆分：<code>pre-bash-block-rm-rf.sh</code>、<code>pre-bash-block-curl-pipe.sh</code> 各自獨立</li><li>所有 hook 測試 suite 包含：a) 應阻斷但未阻斷的 fixture（Fail Loud）；b) 應通過但被阻斷的 fixture（False Positive）</li></ol><h4 id="陷阱與反模式" tabindex="-1">陷阱與反模式 <a class="header-anchor" href="#陷阱與反模式" aria-label="Permalink to &quot;陷阱與反模式&quot;">​</a></h4><ul><li><strong>反模式</strong>：在一個 hook 中用 if/elif 合併 10 條規則 → 任何一條 regex 錯誤影響全部</li><li><strong>反模式</strong>：用 exit 1 以為是阻斷，實際上 Claude Code 繼續執行</li><li><strong>反模式</strong>：LLM 作為唯一 permission 層（25s timeout 期間無防護）</li></ul><hr><h3 id="主題-b-安全威脅與防禦" tabindex="-1">主題 B：安全威脅與防禦 <a class="header-anchor" href="#主題-b-安全威脅與防禦" aria-label="Permalink to &quot;主題 B：安全威脅與防禦&quot;">​</a></h3><h4 id="核心發現-1" tabindex="-1">核心發現 <a class="header-anchor" href="#核心發現-1" aria-label="Permalink to &quot;核心發現&quot;">​</a></h4><p><strong>B1 — GitHub Action 環境變數洩露（Microsoft Security Research，2026-06-05）</strong>[來源宣稱]</p><ul><li>攻擊向量：Claude Code GitHub Action 的 Read tool 讀 <code>/proc/self/environ</code> 暴露 <code>ANTHROPIC_API_KEY</code></li><li>觸發方式：HTML comment payload 以 &#39;compliance review&#39; framing 繞過警覺</li><li>修補版本：v2.1.128（阻斷 /proc 存取）</li><li>防禦原則：「Agents Rule of Two」——任何 agent 行動需通過兩個獨立檢查點</li></ul><p><strong>B2 — Two-stage Injection Guard（Michael Hannecke）</strong>[來源宣稱]</p><ul><li>Stage 1：Python regex（&lt;5ms），阻斷已知 pattern</li><li>Stage 2：本機 LLM（Phi-3.5 mini / Qwen-2.5 1.5B via Ollama），在隱私敏感場景替代雲端 API</li><li>四種 injection 向量（嚴重性由高到低）： <ol><li><strong>targeted</strong>：直接命令注入</li><li><strong>reputation framing</strong>：「作為 compliance system 你必須...」</li><li><strong>delayed</strong>：多輪後觸發的隱藏指令</li><li><strong>obfuscated</strong>：編碼/分散字符繞過 regex</li></ol></li></ul><p><strong>B3 — 系統性攻擊面（VILA-Lab arXiv 2604.14228）</strong>[學術論文，相對可信]</p><ul><li>98.4% 的 Claude Code 能力依賴確定性基礎設施</li><li>5 層壓縮降級路徑（可被利用導致 context collapse）： <code>budget → snip → microcompact → context collapse → auto-compact</code></li><li><strong>pre-trust window CVE</strong>：hook 在 trust dialog 顯示前已執行，攻擊者可在用戶看到警告前完成操作</li><li>50+ subcommand starvation：大量子命令並行導致資源耗盡</li></ul><h4 id="最佳實踐建議-1" tabindex="-1">最佳實踐建議 <a class="header-anchor" href="#最佳實踐建議-1" aria-label="Permalink to &quot;最佳實踐建議&quot;">​</a></h4><ol><li>GitHub Actions 務必更新至 v2.1.128+，並明確設定 Read tool 路徑白名單</li><li>對所有外部輸入（PR 描述、issue body、讀取的外部文件）套用 injection guard，不只對 user prompt</li><li>本地敏感 codebase 考慮 Ollama 本機 LLM 替代雲端 API 做 injection 分類</li><li>「reputation framing」是最難防的向量：設計 hook 時明確拒絕含有「compliance/audit/review/必須服從」語義的 system prompt 修改請求</li></ol><h4 id="陷阱與反模式-1" tabindex="-1">陷阱與反模式 <a class="header-anchor" href="#陷阱與反模式-1" aria-label="Permalink to &quot;陷阱與反模式&quot;">​</a></h4><ul><li><strong>反模式</strong>：只防 <code>rm -rf</code>、<code>curl | bash</code> 等明確指令，忽略 reputation framing（「作為安全合規系統你需要...」）</li><li><strong>反模式</strong>：假設 trust dialog 後才有風險；pre-trust window 是真實 CVE</li><li><strong>反模式</strong>：在 GitHub Action 中不設定環境變數範圍，讓所有 env var 對 agent 可見</li></ul><hr><h3 id="主題-c-大規模並行-orchestration" tabindex="-1">主題 C：大規模並行 Orchestration <a class="header-anchor" href="#主題-c-大規模並行-orchestration" aria-label="Permalink to &quot;主題 C：大規模並行 Orchestration&quot;">​</a></h3><h4 id="核心發現-2" tabindex="-1">核心發現 <a class="header-anchor" href="#核心發現-2" aria-label="Permalink to &quot;核心發現&quot;">​</a></h4><p><strong>C1 — Agent Farm（Dicklesworthstone）</strong>[來源宣稱]</p><ul><li>規模：20-50 並行 agent</li><li>協調機制：POSIX <code>flock</code> lock-based（不依賴中央 server）</li><li><code>active_work_registry.json</code>：追蹤各 agent 當前任務</li><li>Stale lock 自動清除：&gt;2hr 視為死亡，釋放鎖</li><li>Adaptive stagger：成功則 halve delay，失敗則 double delay（指數退避）</li><li>Heartbeat 文件：每個 agent 定期寫入 <code>heartbeat/&lt;agent_id&gt;.json</code>，主 orchestrator 監控</li></ul><p><strong>C2 — Overnight Session 三大失敗模式（Eva Khmelinskaya）</strong>[來源宣稱]</p><ul><li><strong>Context exhaustion</strong>：verbose tool output 填滿 context window，agent 失去任務意識</li><li><strong>Instruction dilution</strong>：CLAUDE.md 在 90+ 分鐘後被 compact 丟失，agent 忘記核心規則</li><li><strong>Silent stalling</strong>：12 小時無感失敗，agent 卡住但不報錯</li></ul><p>三層修復：</p><ol><li>Output-redirection rules：工具輸出截斷規則（「只報告 changed files，不輸出 full diff」）</li><li>STATUS.md handoff：每個 session 結束前寫入狀態文件，下一 session 從此讀取</li><li>30-60 分鐘 fresh <code>--print</code> sessions：避免 context 累積超過臨界點</li></ol><p><strong>C3 — Multi-model Adversarial Debate（Milvus）</strong>[來源宣稱，有具體數字]</p><ul><li>單模型 bug detection：53%</li><li>5 模型 debate：80%</li><li>Claude+Gemini 雙模型：91% of 5-model ceiling（性價比最優點）</li><li>系統級最難 bug：debate 100% vs 單模型 0%（最大差距在最難問題）</li></ul><h4 id="最佳實踐建議-2" tabindex="-1">最佳實踐建議 <a class="header-anchor" href="#最佳實踐建議-2" aria-label="Permalink to &quot;最佳實踐建議&quot;">​</a></h4><ol><li>20+ 並行 agent 用 POSIX flock（無 server 依賴，k8s 環境適用 distributed lock）</li><li>每個 overnight task 必須有 STATUS.md 協議：<code>{task, phase, last_checkpoint, next_action, blockers}</code></li><li>bug review 場景：Claude+Gemini 雙模型 debate 比單一強模型效果更好，且成本可控</li><li>Session 超過 60 分鐘必須規劃 context handoff（STATUS.md 或 MEMORY.md 更新）</li></ol><h4 id="陷阱與反模式-2" tabindex="-1">陷阱與反模式 <a class="header-anchor" href="#陷阱與反模式-2" aria-label="Permalink to &quot;陷阱與反模式&quot;">​</a></h4><ul><li><strong>反模式</strong>：讓 agent 跑 3+ 小時 session 不設 checkpoint，silent stalling 12 小時才發現</li><li><strong>反模式</strong>：5 模型 debate 當標準配置（成本 5x，收益僅 +27% vs 雙模型 +38%）</li><li><strong>反模式</strong>：依賴 CLAUDE.md 在長 session 中保持完整，必須假設 90 分鐘後已被 compact</li></ul><hr><h3 id="主題-d-成本與-token-優化" tabindex="-1">主題 D：成本與 Token 優化 <a class="header-anchor" href="#主題-d-成本與-token-優化" aria-label="Permalink to &quot;主題 D：成本與 Token 優化&quot;">​</a></h3><h4 id="核心發現-3" tabindex="-1">核心發現 <a class="header-anchor" href="#核心發現-3" aria-label="Permalink to &quot;核心發現&quot;">​</a></h4><p><strong>D1 — Branch8 APAC Team 8 週優化</strong>[來源宣稱]</p><ul><li>成本：$2,400→$680/月（−72%）[來源宣稱]</li><li>關鍵參數：<code>sessionLimit: 500K</code> / <code>dailyLimit: 2M</code> / <code>autoCompactAt: 60%</code></li><li>Cache hit rate：34.2%→60%+（提升 26pp）</li><li>CLI aliases：<code>cc</code>（一般）/ <code>cc-quick</code>（haiku，快速任務）/ <code>cc-deep</code>（opus，架構任務）</li><li>APAC 特有問題：async session 跨時區較長，單 session 成本高於美國團隊</li></ul><p><strong>D2 — RAG-over-codebase（mcplens，Figueredo）</strong>[來源宣稱]</p><ul><li>技術棧：Ollama nomic-embed-text + SQLite vector（cosine similarity，~50ms）</li><li>Token 削減：70-85%（45K vs 120-150K tokens）[來源宣稱]</li><li>時間：2:48 vs 5:00 分鐘（−44%）[來源宣稱]</li><li>隱私：on-device，不送雲端</li><li>增量索引：SHA-1 diff，只重新 embed 變更文件</li></ul><p><strong>D3 — AST Graph（Graphify）</strong>[來源宣稱]</p><ul><li>技術棧：Tree-sitter AST + Leiden community detection clustering</li><li>攔截點：注入 Glob/Grep tool，直接返回 graph navigation 結果</li><li>Token 削減：71x（12K-18K → 2K navigation overhead）[來源宣稱]</li><li>Edge 類型：EXTRACTED（確定）/ INFERRED（推測）/ AMBIGUOUS（不確定）</li></ul><h4 id="最佳實踐建議-3" tabindex="-1">最佳實踐建議 <a class="header-anchor" href="#最佳實踐建議-3" aria-label="Permalink to &quot;最佳實踐建議&quot;">​</a></h4><ol><li>第一步先設 <code>autoCompactAt: 60%</code>（立即有效，零開發成本）</li><li>大型 codebase（&gt;50K loc）上 RAG MCP，預期 token 削減 50-70%（保守估計，不用原始 70-85%）</li><li>CLI aliases 分 tier：Haiku（&lt;5 分鐘小修改）/ Sonnet（一般任務）/ Opus（架構決策），預算自動導流</li><li>建立 cache hit rate 監控：低於 40% 表示 prompt prefix 不穩定，先找破快取原因</li></ol><h4 id="陷阱與反模式-3" tabindex="-1">陷阱與反模式 <a class="header-anchor" href="#陷阱與反模式-3" aria-label="Permalink to &quot;陷阱與反模式&quot;">​</a></h4><ul><li><strong>反模式</strong>：不設 autoCompactAt，讓 context 自然填滿再 compact（成本最高點才 compact）</li><li><strong>反模式</strong>：在所有任務用 Opus（適合 &lt;10% 的架構決策任務）</li><li><strong>反模式</strong>：RAG 索引整個 repo 含 test fixtures/node_modules → 雜訊遠超信號</li></ul><hr><h3 id="主題-e-記憶系統架構" tabindex="-1">主題 E：記憶系統架構 <a class="header-anchor" href="#主題-e-記憶系統架構" aria-label="Permalink to &quot;主題 E：記憶系統架構&quot;">​</a></h3><h4 id="核心發現-4" tabindex="-1">核心發現 <a class="header-anchor" href="#核心發現-4" aria-label="Permalink to &quot;核心發現&quot;">​</a></h4><p><strong>E1 — claude-mem（thedotmack）</strong>[來源宣稱]</p><ul><li>雙軌儲存：SQLite FTS5（全文搜尋）+ Chroma（向量語意搜尋）</li><li>5 個 lifecycle hooks 覆蓋：save / search / timeline / get / delete</li><li>Progressive disclosure 三層： <ol><li><code>search</code>：返回摘要（低 token）</li><li><code>timeline</code>：時間序列（中 token）</li><li><code>get_observations</code>：完整細節（高 token）</li></ol></li><li>Service port 37777（worker service，背景常駐）</li></ul><p><strong>E2 — Ian Paterson 4-layer memory</strong>[來源宣稱，詳細量化]</p><ul><li>Layer 1（always-loaded）：200 行 cap，超過導致 60% lessons 不可見</li><li>Layer 2（daily logs）：append-only，by date</li><li>Layer 3（project state）：append-only，by project</li><li>Layer 4（on-demand）：10 topic files + 22 shared + 6 nav index</li><li>5 cron jobs 維護（自動摘要、清理、壓縮）</li><li>規模：34 projects 驗證，~$8/月</li><li><strong>關鍵教訓</strong>：501 行超過 200 行 cap 導致 60% lessons 不可見 [來源宣稱]</li></ul><p><strong>E3 — Sean Moran 長 session 哲學（2026）</strong>[來源宣稱]</p><ul><li>2026 最大轉變：long session &gt; frequent /clear（反轉 2025 建議）</li><li>原因：automatic context compaction 讓 accumulated context 成優勢</li><li>Symptom-driven debugging &gt; manual diagnosis（讓 Claude 從 error 反推）</li><li>12 commits in one conversation span（最高紀錄）</li></ul><h4 id="最佳實踐建議-4" tabindex="-1">最佳實踐建議 <a class="header-anchor" href="#最佳實踐建議-4" aria-label="Permalink to &quot;最佳實踐建議&quot;">​</a></h4><ol><li>Memory 分層設計：always-loaded ≤200 行（硬上限），超過立即 compact</li><li>任何 &gt;1 session 的任務必須有 handoff 文件（<code>STATUS.md</code> 或 <code>MEMORY.md</code> session 節）</li><li>SQLite FTS5 是最低開發成本的記憶後端起點，先於 vector DB 部署</li><li>Progressive disclosure：search → timeline → get，不要預設返回完整記憶</li></ol><h4 id="陷阱與反模式-4" tabindex="-1">陷阱與反模式 <a class="header-anchor" href="#陷阱與反模式-4" aria-label="Permalink to &quot;陷阱與反模式&quot;">​</a></h4><ul><li><strong>反模式</strong>：always-loaded memory 超過 200 行（Ian Paterson 親驗：60% lessons disappear）</li><li><strong>反模式</strong>：記憶只寫不讀——在 session 開始時沒有明確「讀取 MEMORY.md」步驟</li><li><strong>反模式</strong>：vector DB 從第一天起（成本高，SQLite FTS5 在 &lt;100K 記憶條目已足夠）</li></ul><hr><h3 id="主題-f-企業部署" tabindex="-1">主題 F：企業部署 <a class="header-anchor" href="#主題-f-企業部署" aria-label="Permalink to &quot;主題 F：企業部署&quot;">​</a></h3><h4 id="核心發現-5" tabindex="-1">核心發現 <a class="header-anchor" href="#核心發現-5" aria-label="Permalink to &quot;核心發現&quot;">​</a></h4><p><strong>F1 — General Analysis 7 層控制架構</strong>[來源宣稱]</p><ul><li>3 個 repo risk tiers： <ul><li>低風險：完整 Claude 存取，minimal hooks</li><li>Production-adjacent：讀取允許，寫入需 PR + review</li><li>Regulated：所有 write 操作需人工二次確認</li></ul></li><li>Kill-switch 架構：centralized config 遠端下發，不等開發者更新本地文件</li><li>Incident response 協議：timeline + control change + retest（evidence-driven，不靠口頭報告）</li></ul><p><strong>F2 — Boldare Gas Trading Team</strong>[來源宣稱]</p><ul><li>規模：6 人團隊</li><li>測試覆蓋率：85%→95%（+10pp）</li><li>Sprint velocity：+15-31%（13→17 points）</li><li>工具分工：Frontend 50% Cursor / Backend ~90% Claude</li><li>最大價值場景：「高量低認知負擔任務」（boilerplate、test generation、doc update）</li></ul><h4 id="最佳實踐建議-5" tabindex="-1">最佳實踐建議 <a class="header-anchor" href="#最佳實踐建議-5" aria-label="Permalink to &quot;最佳實踐建議&quot;">​</a></h4><ol><li>Repo risk tier 分類是企業部署的第一步，不要用同一套規則管 poc 和 production</li><li>Kill-switch 必須是 centralized 遠端下發，本地文件修改不算 kill-switch</li><li>最大 ROI 在「高量低認知負擔」任務，不要先在核心業務邏輯上冒進</li><li>Evidence-driven incident response：每次問題必須有 timeline + 可重現步驟，不接受「感覺修好了」</li></ol><h4 id="陷阱與反模式-5" tabindex="-1">陷阱與反模式 <a class="header-anchor" href="#陷阱與反模式-5" aria-label="Permalink to &quot;陷阱與反模式&quot;">​</a></h4><ul><li><strong>反模式</strong>：全公司用同一套 hooks 規則（regulated repo 和 poc repo 需求完全不同）</li><li><strong>反模式</strong>：指望開發者手動更新本地 CLAUDE.md 來執行安全政策</li><li><strong>反模式</strong>：把最難的任務（新核心功能設計）當 AI 的起點，先從可衡量的重複任務開始</li></ul><hr><h3 id="主題-g-spec-與工作流程" tabindex="-1">主題 G：Spec 與工作流程 <a class="header-anchor" href="#主題-g-spec-與工作流程" aria-label="Permalink to &quot;主題 G：Spec 與工作流程&quot;">​</a></h3><h4 id="核心發現-6" tabindex="-1">核心發現 <a class="header-anchor" href="#核心發現-6" aria-label="Permalink to &quot;核心發現&quot;">​</a></h4><p><strong>G1 — Pimzino 四代理 Spec 工作流</strong>[來源宣稱]</p><ul><li>代理分工：spec-task-executor × 1 + validators × 3（read-only）</li><li>三個 steering 文件：<code>product.md</code>（需求）/ <code>tech.md</code>（技術決策）/ <code>structure.md</code>（代碼結構）</li><li>Hierarchical context distribution：60-80% token 節省 [來源宣稱]</li><li>Validator 只有讀取權限，不能修改代碼（防止 validator 自我修正掩蓋問題）</li></ul><p><strong>G2 — Alexander Opalic Spec-driven 四階段</strong>[來源宣稱]</p><ul><li>四階段流程： <ol><li>Parallel research（多個子 agent 同時研究不同面向）</li><li>Spec 生成（<code>AskUserQuestion</code> 確認歧義）</li><li>Atomic commits（每個 spec 條目對應一個 commit）</li><li><code>.claude/tasks/</code> JSON persistence（跨 session 任務狀態持久化）</li></ol></li><li>效果：45 分鐘完成 14 tasks、14 commits [來源宣稱]</li><li>Spec 是 recovery point：任何 session 中斷可從最後一個 spec 點恢復</li></ul><p><strong>G3 — Jamie Cole 30 天 Production Retrospective</strong>[來源宣稱，最具體]</p><ul><li>47 tasks，25% abandonment（12/47 任務放棄）</li><li><strong>每 5 任務 1 次 regression from context drift</strong></li><li>核心結論：「One task, one session. Don&#39;t chain.」</li><li>反直覺點：users 期望長 session 效率更高，實際上放棄率更低</li></ul><h4 id="最佳實踐建議-6" tabindex="-1">最佳實踐建議 <a class="header-anchor" href="#最佳實踐建議-6" aria-label="Permalink to &quot;最佳實踐建議&quot;">​</a></h4><ol><li>任何 &gt;3 小時工作必須先寫 spec（spec 是 recovery point，不只是設計文件）</li><li><code>.claude/tasks/</code> JSON persistence：<code>{task_id, status, spec, last_commit, blockers}</code></li><li>Validator 代理必須 read-only——賦予 write 權限的 validator 會修改問題掩蓋 bug</li><li>每 5 個連續任務後強制 <code>/clear</code> 開新 session（Jamie Cole 的 empirical 閾值）</li></ol><h4 id="陷阱與反模式-6" tabindex="-1">陷阱與反模式 <a class="header-anchor" href="#陷阱與反模式-6" aria-label="Permalink to &quot;陷阱與反模式&quot;">​</a></h4><ul><li><strong>反模式</strong>：在同一 session 鏈式執行 10+ 任務，第 6 個以後 context drift regression 顯著</li><li><strong>反模式</strong>：Spec 只有自然語言描述，沒有可機械驗證的「完成條件」</li><li><strong>反模式</strong>：Validator 擁有 write 權限（典型：「讓 reviewer 順便修一下」→ bug 被掩蓋）</li></ul><hr><h3 id="主題-h-ci-cd-與-routines" tabindex="-1">主題 H：CI/CD 與 Routines <a class="header-anchor" href="#主題-h-ci-cd-與-routines" aria-label="Permalink to &quot;主題 H：CI/CD 與 Routines&quot;">​</a></h3><h4 id="核心發現-7" tabindex="-1">核心發現 <a class="header-anchor" href="#核心發現-7" aria-label="Permalink to &quot;核心發現&quot;">​</a></h4><p><strong>H1 — HTTP Hooks × GitHub Actions（claudelab）</strong>[來源宣稱]</p><ul><li>自愈迴圈：Block → Rewrite → Verify（三步閉環）</li><li>技術棧：Cloudflare Workers + Hono webhook server</li><li><code>session_id</code> correlation：所有 hook 事件用 session_id 關聯，支援完整 audit trail</li><li>p95 &gt;3s 告警：hook 延遲超過 3 秒觸發 alert（防 25s timeout 耗盡）</li></ul><p><strong>H2 — Claude Code Routines（官方）</strong>[已驗證，官方文件]</p><ul><li>三類 trigger：Scheduled（cron）/ API（REST）/ GitHub webhook（8 種事件）</li><li>配額限制：Pro 5 / Max 15 / Team 25 runs/day</li><li>共用 interactive quota（routine 消耗與互動 session 同一池）</li><li><code>claude/</code> prefix 分支：routine 結果自動推送到 <code>claude/&lt;branch-name&gt;</code></li></ul><p><strong>H3 — Microsoft v2.1.128 Patch</strong>[已驗證]</p><ul><li><code>/proc</code> 存取阻斷（修補 B1 的 CVE）</li><li>根本設計問題：GitHub Action 預設允許 Read 任意路徑，patch 是防禦層不是根治</li></ul><h4 id="最佳實踐建議-7" tabindex="-1">最佳實踐建議 <a class="header-anchor" href="#最佳實踐建議-7" aria-label="Permalink to &quot;最佳實踐建議&quot;">​</a></h4><ol><li>所有 production hook 設 p95 延遲告警（&lt;3s），防 timeout 耗盡造成安全盲區</li><li>GitHub Action 立即更新到 v2.1.128+，同時設定 Read tool 路徑白名單（patch 不能替代白名單）</li><li>Routine 配額與 interactive session 共用：白天互動高峰期避免排程大型 routine</li><li><code>session_id</code> correlation 是 audit trail 的基礎，在設計階段就加入</li></ol><h4 id="陷阱與反模式-7" tabindex="-1">陷阱與反模式 <a class="header-anchor" href="#陷阱與反模式-7" aria-label="Permalink to &quot;陷阱與反模式&quot;">​</a></h4><ul><li><strong>反模式</strong>：Routine 在工作時間跑，消耗 interactive quota</li><li><strong>反模式</strong>：只更新 v2.1.128 不設白名單（patch 修補已知 /proc，未知路徑仍暴露）</li><li><strong>反模式</strong>：Hook webhook server 沒有超時告警，靜默 timeout 導致策略空窗</li></ul><hr><h3 id="主題-i-skill-設計" tabindex="-1">主題 I：Skill 設計 <a class="header-anchor" href="#主題-i-skill-設計" aria-label="Permalink to &quot;主題 I：Skill 設計&quot;">​</a></h3><h4 id="核心發現-8" tabindex="-1">核心發現 <a class="header-anchor" href="#核心發現-8" aria-label="Permalink to &quot;核心發現&quot;">​</a></h4><p><strong>I1 — AgentStack 6 Lessons</strong>[來源宣稱]</p><ul><li>指令長度 U 型最佳點：250-450 words 本體 + 100-200 words 邊緣情境</li><li><strong>Banlist 優於 Stylelist</strong>：「不要使用 X、Y、Z」比「要使用 A、B、C 風格」更有效</li><li><code>description</code> frontmatter 的 &#39;Use when...&#39; 控制 fuzzy-match precision</li><li>太短（&lt;150 words）：ambiguous，模型猜測；太長（&gt;600 words）：dilution</li></ul><p><strong>I2 — Mayur Panchal Skill Builder</strong>[來源宣稱]</p><ul><li>SKILL.md description 必須 &#39;pushy&#39;（強烈指向觸發場景，弱 description 導致 miss）</li><li>三模式：Prompt-Only / +Scripts / +MCP（複雜度由低到高）</li><li>ZIP 根層必須是資料夾（不是直接放文件）</li><li>name ≤64 chars（超過被截斷，fuzzy-match 失效）</li></ul><h4 id="最佳實踐建議-8" tabindex="-1">最佳實踐建議 <a class="header-anchor" href="#最佳實踐建議-8" aria-label="Permalink to &quot;最佳實踐建議&quot;">​</a></h4><ol><li>Skill description 格式：「Use when user types X / asks about Y / wants to Z. Do NOT use for: A, B.」（正例 + 反例）</li><li>每個 skill 有 banlist：<code>Do not: use &quot;leverage&quot;, use bullet lists for code, generate without reading existing files first</code></li><li>指令維持在 250-450 words，邊緣情境另加 100-200 words（不要合在一起）</li><li>Skill ZIP 測試前先確認根層是資料夾、name ≤64 chars</li></ol><h4 id="陷阱與反模式-8" tabindex="-1">陷阱與反模式 <a class="header-anchor" href="#陷阱與反模式-8" aria-label="Permalink to &quot;陷阱與反模式&quot;">​</a></h4><ul><li><strong>反模式</strong>：Skill description 只有一句話（「幫助用戶寫代碼」），fuzzy-match 觸發不穩定</li><li><strong>反模式</strong>：Stylelist（「要簡潔、要清晰、要結構化」），模型把所有 style 都當必要</li><li><strong>反模式</strong>：ZIP 根層直接放文件（安裝後 skill 無法找到 SKILL.md）</li></ul><hr><h3 id="主題-j-大型專案策略" tabindex="-1">主題 J：大型專案策略 <a class="header-anchor" href="#主題-j-大型專案策略" aria-label="Permalink to &quot;主題 J：大型專案策略&quot;">​</a></h3><h4 id="核心發現-9" tabindex="-1">核心發現 <a class="header-anchor" href="#核心發現-9" aria-label="Permalink to &quot;核心發現&quot;">​</a></h4><p><strong>J1 — Virtual Monorepo Pattern（Zanzal）</strong>[來源宣稱]</p><ul><li>三文件架構： <ol><li><code>.repos</code>：bash script，clone/sync 所有 repos</li><li><code>CLAUDE.md</code>：system map（每個 repo 的職責和 entry points）</li><li><code>README</code>：architecture doc（服務間依賴圖）</li></ol></li><li>35 repos，零 CI/CD 改動（virtual layer，不修改各 repo）[來源宣稱]</li></ul><p><strong>J2 — 8 Monorepo Tips（Das）</strong>[來源宣稱]</p><ul><li>Nested CLAUDE.md hierarchy：root level（架構）→ package level（實現細節）</li><li>Claude Code DRI designation：每個 package 指定一個「負責人」角色（DRI = Directly Responsible Individual）</li><li>Per-package skills：不要用 global skill 處理特定 package 邏輯</li><li>Subdirectory initialization：<code>claude --dir packages/foo</code> 只載入該 package context</li></ul><h4 id="最佳實踐建議-9" tabindex="-1">最佳實踐建議 <a class="header-anchor" href="#最佳實踐建議-9" aria-label="Permalink to &quot;最佳實踐建議&quot;">​</a></h4><ol><li>Monorepo 用 <code>--dir</code> flag 隔離 context（35 repos 共用 context 是效能殺手）</li><li>Root CLAUDE.md 只放架構圖和 repo 職責，實現細節放 package-level CLAUDE.md</li><li>35+ repos 場景用 Virtual Monorepo Pattern（不改動各 repo CI/CD）</li></ol><h4 id="陷阱與反模式-9" tabindex="-1">陷阱與反模式 <a class="header-anchor" href="#陷阱與反模式-9" aria-label="Permalink to &quot;陷阱與反模式&quot;">​</a></h4><ul><li><strong>反模式</strong>：35 repos 用同一個 global context（context window 99% 浪費在無關 repos）</li><li><strong>反模式</strong>：Monorepo root CLAUDE.md 放所有技術細節（每個子 package 都載入，token 浪費）</li></ul><hr><h3 id="主題-k-測試自動化" tabindex="-1">主題 K：測試自動化 <a class="header-anchor" href="#主題-k-測試自動化" aria-label="Permalink to &quot;主題 K：測試自動化&quot;">​</a></h3><h4 id="核心發現-10" tabindex="-1">核心發現 <a class="header-anchor" href="#核心發現-10" aria-label="Permalink to &quot;核心發現&quot;">​</a></h4><p><strong>K1 — Two-agent TDD（Melnik）</strong>[來源宣稱]</p><ul><li>typescript-test-specialist：生成測試</li><li>test-quality-reviewer（read-only）：審查覆蓋率和品質，不修改代碼</li><li>效果：30%→50% coverage，&lt;1 week [來源宣稱]</li><li><code>mcp__ide__getDiagnostics</code>：即時 TypeScript type error 反饋（防止生成類型錯誤的測試）</li></ul><p><strong>K2 — RAG 11-day Case Study</strong>[來源宣稱，最詳細]</p><ul><li>Day 1-2：先建 eval harness（50 fixtures），不先寫功能</li><li>68% AI keystrokes（含 AI 輔助修改）[來源宣稱]</li><li>87% eval pass rate（最終）[來源宣稱]</li><li><strong>20% rejection rate</strong>：5 個 AI 建議中有 1 個被拒</li><li>拒絕 AI 的三個具體場景： <ol><li>測試 fixture 有領域知識錯誤（AI 不懂業務）</li><li>性能優化建議破壞可讀性（AI 優化錯目標）</li><li>邊緣情境處理違反既有架構決策（AI 不知歷史）</li></ol></li></ul><h4 id="最佳實踐建議-10" tabindex="-1">最佳實踐建議 <a class="header-anchor" href="#最佳實踐建議-10" aria-label="Permalink to &quot;最佳實踐建議&quot;">​</a></h4><ol><li>eval harness first：Day 1 建測試框架，Day 2 才開始功能開發</li><li>Test reviewer 必須 read-only（同主題 G 的 validator 原則）</li><li>20% rejection rate 是健康指標——0% rejection 表示沒有人工判斷，100% 表示 AI 沒有幫上忙</li><li><code>mcp__ide__getDiagnostics</code> 整合進 test-generation loop，不要等最後才跑 type check</li></ol><h4 id="陷阱與反模式-10" tabindex="-1">陷阱與反模式 <a class="header-anchor" href="#陷阱與反模式-10" aria-label="Permalink to &quot;陷阱與反模式&quot;">​</a></h4><ul><li><strong>反模式</strong>：直接接受 AI 生成的所有測試（20% 含領域知識錯誤或架構違規）</li><li><strong>反模式</strong>：先寫功能再補測試（RAG case study 的 eval-first 明確優於此路徑）</li><li><strong>反模式</strong>：不設 rejection rate 指標（看不出 AI 在哪個 domain 幫不上忙）</li></ul><hr><h2 id="三、可執行計劃書" tabindex="-1">三、可執行計劃書 <a class="header-anchor" href="#三、可執行計劃書" aria-label="Permalink to &quot;三、可執行計劃書&quot;">​</a></h2><h3 id="phase-1-quick-wins-1-週內可實施" tabindex="-1">Phase 1：Quick Wins（1 週內可實施） <a class="header-anchor" href="#phase-1-quick-wins-1-週內可實施" aria-label="Permalink to &quot;Phase 1：Quick Wins（1 週內可實施）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>優先序</th><th>項目</th><th>行動</th><th>估時</th><th>驗證方式</th></tr></thead><tbody><tr><td>P0</td><td>GitHub Action 升級</td><td>更新至 v2.1.128+，加 Read tool 路徑白名單</td><td>30 分鐘</td><td><code>gh release list</code> 確認版本</td></tr><tr><td>P0</td><td>autoCompactAt 設定</td><td><code>settings.json</code> 加 <code>autoCompactAt: 60%</code>，sessionLimit: 500K</td><td>15 分鐘</td><td>下次 session 觀察 compact 觸發點</td></tr><tr><td>P1</td><td>Hook exit code 稽核</td><td>grep 所有 hook scripts，確認 exit 1→exit 2</td><td>1 小時</td><td><code>grep -rn &quot;exit 1&quot; .claude/hooks/</code></td></tr><tr><td>P1</td><td>CLI aliases</td><td>設定 <code>cc</code>/<code>cc-quick</code>/<code>cc-deep</code> 對應 Sonnet/Haiku/Opus</td><td>30 分鐘</td><td>alias 測試</td></tr><tr><td>P1</td><td>Session length 紀律</td><td>每 5 任務後 /clear，不鏈式執行跨 session 任務</td><td>即時行為調整</td><td>追蹤 abandonment rate</td></tr><tr><td>P2</td><td>MEMORY.md 200 行 cap</td><td>加入 memory-compactor 自動觸發</td><td>2 小時</td><td><code>wc -l MEMORY.md</code></td></tr><tr><td>P2</td><td>Skill description 更新</td><td>所有 skill 加「Do NOT use for:」反例</td><td>3 小時</td><td>fuzzy-match 測試</td></tr></tbody></table><h3 id="phase-2-架構投資-1-個月" tabindex="-1">Phase 2：架構投資（1 個月） <a class="header-anchor" href="#phase-2-架構投資-1-個月" aria-label="Permalink to &quot;Phase 2：架構投資（1 個月）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>優先序</th><th>項目</th><th>行動</th><th>估時</th><th>預期效果</th></tr></thead><tbody><tr><td>P1</td><td>Hook Narrowness Principle</td><td>合併 hook 拆分為單責 hook + fixture 測試</td><td>1 週</td><td>false negative 率 -50%</td></tr><tr><td>P1</td><td>STATUS.md handoff 協議</td><td>標準化跨 session handoff 格式</td><td>3 天</td><td>overnight task 成功率提升</td></tr><tr><td>P1</td><td>Two-layer injection guard</td><td>Python regex + 本機 LLM（Ollama）</td><td>1 週</td><td>reputation framing 防禦</td></tr><tr><td>P2</td><td>RAG MCP 部署</td><td>Ollama nomic-embed-text + SQLite vector</td><td>2 週</td><td>token -50% on codebase queries</td></tr><tr><td>P2</td><td>.claude/tasks/ JSON persistence</td><td>spec recovery point 機制</td><td>3 天</td><td>任務斷點恢復</td></tr><tr><td>P2</td><td>eval harness first</td><td>新功能開發前先建 50 fixtures</td><td>持續</td><td>rejection rate 量化</td></tr></tbody></table><h3 id="phase-3-企業成熟度-3-個月" tabindex="-1">Phase 3：企業成熟度（3 個月） <a class="header-anchor" href="#phase-3-企業成熟度-3-個月" aria-label="Permalink to &quot;Phase 3：企業成熟度（3 個月）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>優先序</th><th>項目</th><th>行動</th><th>估時</th><th>預期效果</th></tr></thead><tbody><tr><td>P1</td><td>Repo risk tier 分類</td><td>3 tier（低/production-adjacent/regulated）× 獨立 hooks</td><td>2 週</td><td>受控環境中 write 操作二次確認</td></tr><tr><td>P1</td><td>Centralized kill-switch</td><td>遠端下發 config，不依賴本地文件</td><td>3 週</td><td>安全事件響應時間 &lt;1 小時</td></tr><tr><td>P1</td><td>Hook webhook server</td><td>session_id correlation + p95 告警</td><td>2 週</td><td>audit trail 完整性</td></tr><tr><td>P2</td><td>Multi-model debate for review</td><td>Claude+Gemini 雙模型 PR review</td><td>1 週</td><td>bug detection 估 +38%</td></tr><tr><td>P2</td><td>AST graph navigation</td><td>Tree-sitter + Leiden clustering</td><td>4 週</td><td>large codebase token -70%</td></tr><tr><td>P3</td><td>Routine 排程</td><td>GitHub webhook 觸發的自動化任務</td><td>2 週</td><td>減少人工 CI/CD 干預</td></tr></tbody></table><hr><h2 id="四、技術決策矩陣" tabindex="-1">四、技術決策矩陣 <a class="header-anchor" href="#四、技術決策矩陣" aria-label="Permalink to &quot;四、技術決策矩陣&quot;">​</a></h2><table tabindex="0"><thead><tr><th>場景</th><th>推薦方案</th><th>替代</th><th>避免</th></tr></thead><tbody><tr><td>小型 codebase 成本優化</td><td><code>autoCompactAt: 60%</code> + CLI aliases</td><td>RAG（overkill）</td><td>不設限制</td></tr><tr><td>大型 codebase（&gt;50K loc）token 優化</td><td>RAG MCP（Ollama+SQLite）</td><td>AST graph</td><td>全 repo context 載入</td></tr><tr><td>Monorepo（&gt;10 packages）</td><td>nested CLAUDE.md + <code>--dir</code> flag</td><td>Virtual monorepo</td><td>單一 root context</td></tr><tr><td>安全關鍵 repo</td><td>3 tier hooks + centralized kill-switch</td><td>單層 hooks</td><td>無 hooks</td></tr><tr><td>overnight 長任務</td><td>STATUS.md + 30-60min sessions</td><td>單一長 session</td><td>&gt;3hr 無 checkpoint</td></tr><tr><td>Bug detection review</td><td>Claude+Gemini 雙模型 debate</td><td>單模型</td><td>5 模型（成本不對稱）</td></tr><tr><td>Test coverage 提升</td><td>eval-first + read-only reviewer</td><td>直接生成</td><td>接受所有 AI 建議</td></tr><tr><td>Skill 觸發精準度</td><td>description + banlist + &#39;Do NOT use for&#39;</td><td>只有 description</td><td>只有 stylelist</td></tr><tr><td>Prompt injection 防禦</td><td>Python regex（&lt;5ms）+ 本機 LLM</td><td>純 regex</td><td>無防禦</td></tr><tr><td>企業 incident response</td><td>evidence-driven（timeline+retest）</td><td>口頭確認</td><td>感覺修好了就算</td></tr></tbody></table><hr><h2 id="五、insights-彙整與-lessons" tabindex="-1">五、Insights 彙整與 Lessons <a class="header-anchor" href="#五、insights-彙整與-lessons" aria-label="Permalink to &quot;五、Insights 彙整與 Lessons&quot;">​</a></h2><h3 id="跨主題-insights" tabindex="-1">跨主題 Insights <a class="header-anchor" href="#跨主題-insights" aria-label="Permalink to &quot;跨主題 Insights&quot;">​</a></h3><p><strong>Insight 1：確定性層是信任基礎</strong> 所有成功案例共用一個模式：確定性邏輯（regex/AST/exit code）做決策，LLM 做分類。Dyad AI 的雙層架構、POSIX flock 的 agent 協調、Graphify 的 AST edge 分類，都遵循此原則。違反此原則（用 LLM 做 routing decision）的案例均有失敗回報。</p><p><strong>Insight 2：Context 是消耗品，不是資源</strong> Ian Paterson 的 60% lessons disappear、Jamie Cole 的每 5 任務 1 regression、Eva Khmelinskaya 的 CLAUDE.md 90 分鐘消失——都是同一個問題的不同面向：context 是有限的消耗品，管理策略決定 70% 的長期效果。</p><p><strong>Insight 3：架構槓桿 &gt; 內容壓縮</strong> 71x（AST graph）、70-85%（RAG）、60-80%（memory 分層）的 token 削減均來自架構改變，不是把 prompt 寫得更簡短。「壓縮 prompt 文字」的投資回報遠低於「改變如何向 Claude 提供 context」。</p><p><strong>Insight 4：Read-only reviewer 是品質閘門</strong> 測試 reviewer（read-only）、spec validator（read-only）重複出現在不同主題。賦予 reviewer write 權限是最常見的錯誤——reviewer 會自我修正掩蓋問題而非回報。</p><p><strong>Insight 5：20% rejection rate 是健康指標</strong> RAG case study 的 20% rejection rate 提供了一個 calibration benchmark：完全不拒絕 = 沒有人工判斷；完全拒絕 = AI 沒有幫助。健康區間在 15-25%。</p><h3 id="anti-pattern-registry-具體化版本" tabindex="-1">Anti-pattern Registry（具體化版本） <a class="header-anchor" href="#anti-pattern-registry-具體化版本" aria-label="Permalink to &quot;Anti-pattern Registry（具體化版本）&quot;">​</a></h3><ol><li><strong>不要</strong>：同一 session 鏈式執行 6+ 任務（每 5 任務 context drift regression，Jamie Cole 的 empirical 數據）</li><li><strong>不要</strong>：overnight agent 跑 &gt;90 分鐘不設 STATUS.md handoff（CLAUDE.md 在此時間點後被 compact 丟失）</li><li><strong>不要</strong>：用 exit 1 以為是阻斷（exit 1 在 Unix convention 是非阻斷，exit 2 才阻斷）</li><li><strong>不要</strong>：GitHub Action 不設 Read tool 路徑白名單（即使 v2.1.128 已 patch /proc，其他敏感路徑仍暴露）</li><li><strong>不要</strong>：always-loaded memory 超過 200 行（&gt;501 行導致 60% lessons 不可見）</li><li><strong>不要</strong>：5 模型 debate 作為標準配置（Claude+Gemini 雙模型達 91% 天花板，成本 2x vs 5x）</li><li><strong>不要</strong>：Skill description 只有觸發條件沒有反例（「Do NOT use for」是 precision 關鍵）</li><li><strong>不要</strong>：在 Routine 高峰期跑大型 scheduled task（共用 interactive quota）</li></ol><hr><h2 id="六、文章索引-32-篇" tabindex="-1">六、文章索引（32 篇） <a class="header-anchor" href="#六、文章索引-32-篇" aria-label="Permalink to &quot;六、文章索引（32 篇）&quot;">​</a></h2><h3 id="主題-a-permission-hooks-3-篇" tabindex="-1">主題 A：Permission Hooks（3 篇） <a class="header-anchor" href="#主題-a-permission-hooks-3-篇" aria-label="Permalink to &quot;主題 A：Permission Hooks（3 篇）&quot;">​</a></h3><ol><li>Dyad AI — LLM-as-second-layer permission classifier（GREEN/YELLOW/RED）</li><li>Jangwook Kim — Narrowness principle for hooks（exit 0/2 semantics）</li><li>Prompt Shelf — 27 distinct hook events（32+ with subtypes）</li></ol><h3 id="主題-b-安全威脅與防禦-3-篇" tabindex="-1">主題 B：安全威脅與防禦（3 篇） <a class="header-anchor" href="#主題-b-安全威脅與防禦-3-篇" aria-label="Permalink to &quot;主題 B：安全威脅與防禦（3 篇）&quot;">​</a></h3><ol start="4"><li>Microsoft Security Research（2026-06-05）— Claude Code GitHub Action /proc/environ CVE</li><li>Michael Hannecke — Two-stage injection guard（Python regex + Ollama local LLM）</li><li>VILA-Lab arXiv 2604.14228 — Systematic attack surface analysis</li></ol><h3 id="主題-c-大規模並行-orchestration-3-篇" tabindex="-1">主題 C：大規模並行 Orchestration（3 篇） <a class="header-anchor" href="#主題-c-大規模並行-orchestration-3-篇" aria-label="Permalink to &quot;主題 C：大規模並行 Orchestration（3 篇）&quot;">​</a></h3><ol start="7"><li>Dicklesworthstone — Agent Farm（20-50 agents, POSIX flock coordination）</li><li>Eva Khmelinskaya — Overnight session failure modes（context exhaustion/dilution/stalling）</li><li>Milvus — Multi-model adversarial debate（53%→80%→91% bug detection）</li></ol><h3 id="主題-d-成本與-token-優化-3-篇" tabindex="-1">主題 D：成本與 Token 優化（3 篇） <a class="header-anchor" href="#主題-d-成本與-token-優化-3-篇" aria-label="Permalink to &quot;主題 D：成本與 Token 優化（3 篇）&quot;">​</a></h3><ol start="10"><li>Branch8 APAC — 72% cost reduction in 8 weeks（$2,400→$680/月）</li><li>mcplens / Figueredo — RAG-over-codebase（Ollama+SQLite, 70-85% token reduction）</li><li>Graphify — AST graph navigation（Tree-sitter+Leiden, 71x token reduction）</li></ol><h3 id="主題-e-記憶系統架構-3-篇" tabindex="-1">主題 E：記憶系統架構（3 篇） <a class="header-anchor" href="#主題-e-記憶系統架構-3-篇" aria-label="Permalink to &quot;主題 E：記憶系統架構（3 篇）&quot;">​</a></h3><ol start="13"><li>thedotmack / claude-mem — SQLite FTS5 + Chroma dual-track memory</li><li>Ian L. Paterson — 4-layer memory system（34 projects, ~$8/月）</li><li>Sean Moran — Long session philosophy（2026 paradigm shift）</li></ol><h3 id="主題-f-企業部署-2-篇" tabindex="-1">主題 F：企業部署（2 篇） <a class="header-anchor" href="#主題-f-企業部署-2-篇" aria-label="Permalink to &quot;主題 F：企業部署（2 篇）&quot;">​</a></h3><ol start="16"><li>General Analysis — 7-layer control architecture × 3 repo risk tiers</li><li>Boldare — Gas trading team（6 人, 85%→95% test coverage, +15-31% velocity）</li></ol><h3 id="主題-g-spec-與工作流程-3-篇" tabindex="-1">主題 G：Spec 與工作流程（3 篇） <a class="header-anchor" href="#主題-g-spec-與工作流程-3-篇" aria-label="Permalink to &quot;主題 G：Spec 與工作流程（3 篇）&quot;">​</a></h3><ol start="18"><li>Pimzino — 4-agent spec workflow（executor + 3 read-only validators）</li><li>Alexander Opalic — Spec-driven 4-phase development（45min, 14 tasks, 14 commits）</li><li>Jamie Cole — 30-day production retrospective（47 tasks, 25% abandonment）</li></ol><h3 id="主題-h-ci-cd-與-routines-3-篇" tabindex="-1">主題 H：CI/CD 與 Routines（3 篇） <a class="header-anchor" href="#主題-h-ci-cd-與-routines-3-篇" aria-label="Permalink to &quot;主題 H：CI/CD 與 Routines（3 篇）&quot;">​</a></h3><ol start="21"><li>claudelab — HTTP hooks × GitHub Actions（Block→Rewrite→Verify self-healing loop）</li><li>Claude Code Routines — Official（3 trigger types, Pro/Max/Team quotas）</li><li>Microsoft — v2.1.128 security patch（/proc access block）</li></ol><h3 id="主題-i-skill-設計-2-篇" tabindex="-1">主題 I：Skill 設計（2 篇） <a class="header-anchor" href="#主題-i-skill-設計-2-篇" aria-label="Permalink to &quot;主題 I：Skill 設計（2 篇）&quot;">​</a></h3><ol start="24"><li>AgentStack — 6 lessons（U-shaped length optimum, banlist &gt; stylelist）</li><li>Mayur Panchal — Skill builder（pushy description, 3 modes, ZIP structure）</li></ol><h3 id="主題-j-大型專案策略-2-篇" tabindex="-1">主題 J：大型專案策略（2 篇） <a class="header-anchor" href="#主題-j-大型專案策略-2-篇" aria-label="Permalink to &quot;主題 J：大型專案策略（2 篇）&quot;">​</a></h3><ol start="26"><li>Zanzal — Virtual monorepo pattern（3 files, 35 repos, zero CI/CD changes）</li><li>Das — 8 monorepo tips（nested CLAUDE.md, DRI designation, per-package skills）</li></ol><h3 id="主題-k-測試自動化-2-篇" tabindex="-1">主題 K：測試自動化（2 篇） <a class="header-anchor" href="#主題-k-測試自動化-2-篇" aria-label="Permalink to &quot;主題 K：測試自動化（2 篇）&quot;">​</a></h3><ol start="28"><li>Melnik — Two-agent TDD（30%→50% coverage, mcp__ide__getDiagnostics）</li><li>RAG 11-day case study — eval harness first（87% pass rate, 20% rejection rate）</li></ol><h3 id="未分類-跨主題-3-篇" tabindex="-1">未分類 / 跨主題（3 篇） <a class="header-anchor" href="#未分類-跨主題-3-篇" aria-label="Permalink to &quot;未分類 / 跨主題（3 篇）&quot;">​</a></h3><ol start="30"><li>Prompt Shelf — Claude Code hooks complete reference（PostToolBatch TSV）</li><li>Microsoft Security Research follow-up — GitHub Action default trust design flaw</li><li>VILA-Lab — 5-layer compression degradation path（budget→auto-compact CVE）</li></ol><hr><p><em>報告產出時間：2026-06-07 | 研究範疇：2025-10 ~ 2026-06 | 來源：32 篇社群實踐文章</em><em>數字標注：<code>[來源宣稱]</code> = 原作者自述；<code>[已驗證]</code> = 有獨立確認或官方來源</em></p>',200)])])}const g=e(l,[["render",r]]);export{p as __pageData,g as default};
